from qb import q, write

CX = ["mobile-app-developer", "frontend-developer", "full-stack-developer", "backend-developer"]
ITEMS = [
    q("flutter", "easy", ["widgets"], "What is a widget in Flutter and how do StatelessWidget and StatefulWidget differ?", "Everything in Flutter's UI is a widget, a description of part of the screen. A StatelessWidget never changes after it is built, while a StatefulWidget has a State object that holds changing data and rebuilds when setState is called.", ["Widgets describe the UI", "State object for changing data", "setState rebuilds"], ["How do you keep a widget rebuild cheap?"]),
    q("flutter", "medium", ["state-management"], "Compare setState, Provider and Bloc for state management and say when each fits.", "setState suits local state in one widget. Provider shares state across a subtree with little code, and Bloc separates events and states into a predictable structure for larger apps. Choose by app size and team.", ["Local vs shared state", "Provider is simple", "Bloc is structured"], ["How do you test business logic in Bloc?"]),
    q("flutter", "medium", ["lifecycle"], "How does Flutter render the UI and what is the difference between hot reload and hot restart?", "Flutter draws its own widgets with its rendering engine and rebuilds the widget tree efficiently when state changes. Hot reload injects changed code and keeps the state, while hot restart restarts the app and resets state.", ["Own rendering engine", "Hot reload keeps state", "Hot restart resets state"], ["Why can hot reload fail to show a change?"]),
    q("flutter", "hard", ["performance"], "A Flutter list with thousands of items scrolls slowly. How do you fix it?", "Use ListView.builder so items are built lazily, keep item widgets simple and const where possible, avoid heavy work in build, cache images and profile with DevTools to find rebuilds and expensive frames.", ["Lazy builders", "Cheap build methods", "Profile with DevTools"], ["What is jank?"]),
    q("flutter", "medium", ["async"], "How do Future, async and await and Streams work in Dart and when do you use a Stream?", "A Future represents a single value that arrives later and await pauses a function until it completes. A Stream delivers a sequence of values over time, such as location updates or chat messages.", ["Future is one value later", "await pauses the function", "Stream is many values"], ["How do you cancel a stream subscription?"]),
    q("react", "easy", ["react"], "What is the difference between controlled and uncontrolled inputs in React?", "A controlled input keeps its value in React state and updates through onChange, so React is the source of truth. An uncontrolled input keeps its value in the DOM and you read it with a ref when needed.", ["State as source of truth", "Refs for uncontrolled", "Controlled is easier to validate"], ["Which is better for a large form?"]),
    q("react", "medium", ["hooks"], "What are custom hooks and why would you write one for data fetching?", "A custom hook is a function that uses other hooks to package reusable stateful logic. A data fetching hook handles loading, error and data once, so components stay small and consistent.", ["Reusable stateful logic", "Loading, error, data", "Smaller components"], ["What are the rules of hooks?"]),
    q("react", "hard", ["rendering"], "What causes unnecessary re-renders in React and how do memo, useCallback and useMemo help or hurt?", "A component re-renders when its state, props or context change, including new object or function props created each render. memo, useCallback and useMemo skip work when inputs are unchanged, but they add overhead and complexity, so use them where profiling shows a problem.", ["New references cause re-renders", "Memoisation tools", "Profile before optimising"], ["When does useMemo make code slower?"]),
    q("mobile", "medium", ["api"], "How should a mobile app store an authentication token securely?", "Use the platform's secure storage, the Keychain on iOS and the Keystore with encrypted preferences on Android, not plain preferences or logs. Use short-lived tokens with refresh and clear them on logout.", ["Secure storage", "Short-lived tokens", "Clear on logout"], ["Why is a hard-coded API key in the app a problem?"]),
    q("mobile", "medium", ["push"], "How do push notifications work and what must you handle on the server and in the app?", "The app registers with the platform's push service and gives its token to your server, the server sends messages through that service and the device displays them. Handle token refresh, permissions, invalid tokens and opening the right screen on tap.", ["Token registration", "Server sends through the push service", "Permissions and deep links"], ["How would you avoid notifying a user on every device?"]),
    q("mobile", "hard", ["offline"], "How would you build a notes app that works offline and syncs when the network returns?", "Store notes in a local database, queue changes with timestamps and ids, sync in the background with retries and resolve conflicts with a defined rule such as last write wins or merge. Show sync status.", ["Local database first", "Change queue with ids", "Conflict rule"], ["How do you avoid duplicates when a sync is retried?"]),
    q("mobile", "easy", ["release"], "What steps does it take to publish an app update to Google Play or the App Store?", "Increase the version, build a signed release, test it, upload it with release notes and screenshots, pass the store review and roll out gradually. Keep older app versions working with your API.", ["Signed release build", "Store review", "Staged rollout"], ["How do you roll back a bad release?"]),
    q("blockchain", "easy", ["basics"], "What is a blockchain and why is it hard to change past records?", "A blockchain is a shared ledger of blocks, each containing the hash of the previous block. Changing an old block changes its hash and breaks all later blocks, and many independent nodes would reject the altered chain.", ["Linked blocks by hash", "Tampering breaks the chain", "Many independent nodes"], ["What does consensus mean?"]),
    q("blockchain", "medium", ["smart-contracts"], "What is a smart contract and what are its main risks?", "A smart contract is code stored on a blockchain that runs when conditions are met. Once deployed it is hard to change, so bugs such as reentrancy or bad access control can cost real money, which makes testing and audits essential.", ["Code on a blockchain", "Immutable once deployed", "Testing and audits"], ["What is a reentrancy attack?"]),
    q("blockchain", "hard", ["integration"], "How would a mobile or web app interact with a blockchain wallet safely?", "Never handle the user's private key yourself, ask a wallet to sign transactions, show clear transaction details before signing, verify results on-chain and handle slow confirmations and failures.", ["Keys stay in the wallet", "Clear signing prompts", "Confirmations and failures"], ["Why must you not trust the front end alone for balances?"]),
    q("api", "medium", ["rest"], "How do you design a mobile-friendly API with pagination, partial updates and versioning?", "Use cursor or page based pagination with small page sizes, PATCH for partial updates, compress and limit payloads and version the API so older app versions keep working. Return clear errors.", ["Pagination and small payloads", "PATCH", "Versioning for old apps"], ["How do you force users to update an old app?"]),
    q("api", "hard", ["auth"], "How does OAuth login with Google or Apple work in a mobile app at a high level?", "The app opens the provider's login, the user approves and the provider returns a code or token to the app, which your server verifies with the provider before creating its own session. Never trust a token without verifying it on the server.", ["Provider handles credentials", "Code or token returned", "Server verifies the token"], ["What is the benefit of PKCE?"]),
    q("node", "medium", ["backend"], "How would you build a simple Node.js API for a mobile app with authentication and a database?", "Use Express or similar with routes and validation, hash passwords with bcrypt, issue short-lived JWTs, use a database through a driver or ORM with migrations, handle errors centrally and add logging and rate limiting.", ["Routes and validation", "Password hashing and JWT", "Database and error handling"], ["How would you deploy it?"]),
    q("sql", "medium", ["database"], "When would you use SQLite on a device versus a remote database, and how do you handle schema changes in the app?", "SQLite stores local data for offline use and fast access, while a remote database is the shared source of truth. Schema changes in an app need versioned migrations that run on update without losing user data.", ["Local vs remote data", "Versioned migrations", "Never lose user data"], ["How do you test a migration?"]),
    q("testing", "medium", ["mobile-testing"], "How do you test a mobile app across many devices and OS versions?", "Use unit and widget tests for logic and UI, automated integration tests, a device farm or a set of representative real devices and beta testing, and prioritise devices by user statistics. Add crash reporting.", ["Layers of tests", "Representative devices", "Beta and crash reports"], ["How do you decide which devices to support?"]),
    q("cubix-scenario", "medium", ["debugging"], "Scenario: your app works fine on Wi-Fi but users on slow mobile data see long loading screens. What do you do?", "Measure the request sizes and timings, reduce payloads and image sizes, cache data, load content progressively with placeholders, set sensible timeouts and test with network throttling.", ["Measure first", "Smaller payloads and caching", "Progressive loading and throttled tests"], ["How would you show progress honestly?"], kind="scenario"),
    q("cubix-scenario", "hard", ["design"], "Scenario: design a food delivery app's order tracking screen that updates in near real time.", "The server stores order status changes and pushes updates through WebSockets or push notifications, the app shows the latest status and falls back to polling, and the courier's location is sent at a limited frequency to subscribed customers only.", ["Server-driven status updates", "Fallback to polling", "Limited, private location sharing"], ["How would you save battery?"], kind="scenario"),
    q("cubix-scenario", "easy", ["teamwork"], "Scenario: the client changes the design after you finished the screen. How do you respond?", "Look at the change and its cost, explain the impact on time, offer to reuse components to make it cheap and agree the change in writing with the project lead before starting.", ["Assess the impact", "Reuse components", "Agree in writing"], ["How do you build screens that are easy to restyle?"], kind="scenario"),
    q("git", "easy", ["git"], "How do you work with branches and pull requests in a mobile team to avoid breaking the main branch?", "Create a branch per feature, keep changes small, run automated tests on the pull request, get a review and merge only when checks pass. Tag releases so you can rebuild or hotfix an exact version.", ["Branch per feature", "Checks before merge", "Tag releases"], ["How do you handle a hotfix for a released version?"]),
    q("project", "easy", ["projects"], "Describe a mobile or web app you built. What did you build yourself, which package or library did you rely on and what was hard to get right?", "A strong answer names the app and your role, explains the tools chosen and why, and describes a real difficulty such as state, navigation or performance and how it was solved.", ["Own role and tools", "Reason for choices", "A real difficulty and fix"], ["What would you improve first?"], kind="scenario", roles=CX),
]


def build():
    return write("cubix", CX, ITEMS)


if __name__ == "__main__":
    build()
